package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

const Osn = 1000000007

type Pair struct {
	First  int64
	Second int64
}

type PairComparer struct{}

func (pc PairComparer) Compare(x, y Pair) int {
	if x.First < y.First || (x.First == y.First && x.Second > y.Second) {
		return -1
	}
	return 1
}

func GetGcd(a, b int64) int64 {
	for {
		if b == 0 {
			return a
		}
		a1 := a
		a = b
		b = a1 % b
	}
}

var reader = bufio.NewReader(os.Stdin)
var writer = bufio.NewWriter(os.Stdout)

func WriteYesNo(x bool, yes string, no string) {
	if x {
		fmt.Fprintln(writer, yes)
	} else {
		fmt.Fprintln(writer, no)
	}
}

func ReadString() string {
	line, _ := reader.ReadString('\n')
	for len(line) > 0 && (line[len(line)-1] == '\n' || line[len(line)-1] == '\r') {
		line = line[:len(line)-1]
	}
	return line
}

func ReadListOfInts() []int {
	line := ReadString()
	parts := splitBySpace(line)
	res := make([]int, len(parts))
	for i, p := range parts {
		var v int
		fmt.Sscanf(p, "%d", &v)
		res[i] = v
	}
	return res
}

func ReadListOfLongs() []int64 {
	line := ReadString()
	parts := splitBySpace(line)
	res := make([]int64, len(parts))
	for i, p := range parts {
		var v int64
		fmt.Sscanf(p, "%d", &v)
		res[i] = v
	}
	return res
}

func ReadInt() int {
	var v int
	fmt.Sscanf(ReadString(), "%d", &v)
	return v
}

func ReadLong() int64 {
	var v int64
	fmt.Sscanf(ReadString(), "%d", &v)
	return v
}

func splitBySpace(s string) []string {
	var res []string
	cur := ""
	for _, c := range s {
		if c == ' ' {
			if cur != "" {
				res = append(res, cur)
				cur = ""
			}
		} else {
			cur += string(c)
		}
	}
	if cur != "" {
		res = append(res, cur)
	}
	return res
}

type Vertex struct {
	Was   int
	Edges []int
}

var Graph []Vertex

func Dfs(u int) bool {
	if Graph[u].Was == 1 {
		return true
	}
	if Graph[u].Was == 2 {
		return false
	}
	Graph[u].Was = 1
	for _, t := range Graph[u].Edges {
		if Dfs(t) {
			return true
		}
	}
	Graph[u].Was = 2
	return false
}

func IsPrime(x int) bool {
	for j := 2; j*j <= x; j++ {
		if x%j == 0 {
			return false
		}
	}
	return true
}

type LinkedVertex struct {
	Next  int
	Prev  int
	Value int
}

func BinarySearch(list []int, value int) int {
	l := -1
	r := len(list)
	for r-l > 1 {
		m := (r + l) / 2
		if list[m] >= value {
			r = m
		} else {
			l = m
		}
	}
	return r
}

func main() {
	defer writer.Flush()
	_ = sort.Ints
	s := ReadString()
	var ans int64 = 0
	var tt int64 = 1
	for i := len(s) - 1; i >= 0; i-- {
		if s[i] == '>' {
			ans = (ans + tt*8) % 1000003
		}
		if s[i] == '<' {
			ans = (ans + tt*9) % 1000003
		}
		if s[i] == '+' {
			ans = (ans + tt*10) % 1000003
		}
		if s[i] == '-' {
			ans = (ans + tt*11) % 1000003
		}
		if s[i] == '.' {
			ans = (ans + tt*12) % 1000003
		}
		if s[i] == ',' {
			ans = (ans + tt*13) % 1000003
		}
		if s[i] == '[' {
			ans = (ans + tt*14) % 1000003
		}
		if s[i] == ']' {
			ans = (ans + tt*15) % 1000003
		}
		tt = (tt * 16) % 1000003
	}
	fmt.Fprintln(writer, ans)
}
